export interface Invoice {
  id: number;
  invoiceNumber: string;
  /** Batch 1C: an opening receivable migrated at cut-off (amount-only; no VAT, ICV, hash or QR). Its number is the previous system's for a first migration, or OPEN-<batch>-<seq> for a replacement. */
  isOpening?: boolean;
  /**
     * Policy C: set when the migration that created this opening item was reversed. The row is history — frozen, excluded from every receivable figure and from the live list, readable by id. NULL otherwise.
     * @nullable
     */
  reversedAt?: string | null;
  /** @nullable */
  reversedByMigrationBatchId?: number | null;
  /**
     * Policy C: the reversed opening invoice this replacement item stands in for (provenance).
     * @nullable
     */
  replacesInvoiceId?: number | null;
  date: string;
  /** @nullable */
  dueDate: string | null;
  /** @nullable */
  customerId: number | null;
  /** @nullable */
  customerName: string | null;
  status: InvoiceStatus;
  subtotal: number;
  vatAmount: number;
  discount: number;
  total: number;
  /** @nullable */
  currency: string | null;
  paidAmount: number;
  /** D-4 — the part settled by credit notes (Σ credit-note allocations to this invoice). Outstanding = total − paidAmount − creditedAmount. */
  creditedAmount: number;
  /** @nullable */
  paidAt: string | null;
  /** @nullable */
  reviewNote: string | null;
  /** @nullable */
  notes: string | null;
  /**
     * ZATCA hash-chain link; null until the invoice is approved.
     * @nullable
     */
  invoiceHash: string | null;
  /** @nullable */
  previousHash: string | null;
  /**
     * ZATCA Phase-1 QR (base64 TLV); null until approved.
     * @nullable
     */
  qrCode: string | null;
  /** invoice (388) | credit_note (381) | debit_note (383) | advance_invoice (386, AP-2 — the advance tax invoice for a deposit; NOT a receivable) | advance_credit_note (381, AP-3 — the credit note against a 386; returns the advance's VAT to the deposit, is never a credit balance) | recovery_invoice (388, 2026-09-22 — the Art. 40(9) tax invoice for consideration received after bad-debt relief; NOT a receivable) — amounts are stored POSITIVE; direction lives here (documentSign). */
  documentType: InvoiceDocumentType;
  /**
     * For a credit/debit note, the invoice it adjusts.
     * @nullable
     */
  originalInvoiceId: number | null;
  /** @nullable */
  noteReason: string | null;
  /**
     * ZATCA invoice counter value; null until approved.
     * @nullable
     */
  icv: number | null;
  /** @nullable */
  zatcaUuid: string | null;
  /**
     * AP-2: on an advance tax invoice, the receipt (payment id) whose deposit it declares VAT for; null otherwise.
     * @nullable
     */
  advancePaymentId: number | null;
  /**
     * FA-C (2026-09-22): the fixed asset this tax invoice SELLS. Its revenue line then credits the disposal gain/loss account instead of SALES (IAS 16.68 — a disposal is not revenue) and approval derecognises the asset on the same entry. A restricted motor vehicle bought without deduction must be sold with NO VAT (Art. 50(3)) — a VAT-bearing invoice is refused.
     * @nullable
     */
  disposesAssetId?: number | null;
  /**
     * 2026-09-22, opening items only: the previous solution's e-invoicing status of the document; null = not stated (a credit note against it is refused until recorded).
     * @nullable
     */
  openingEinvoicingStatus?: InvoiceOpeningEinvoicingStatus;
  /**
     * 2026-09-22, opening items only: the previous solution's document UUID.
     * @nullable
     */
  openingSourceUuid?: string | null;
  /**
     * 2026-09-22: on a reversed ORIGINAL corrected item-by-item (A4 + answer 5), the correction entry whose other side is retained earnings.
     * @nullable
     */
  openingCorrectionJournalEntryId?: number | null;
  /** 2026-09-22: the unpaid consideration written off as a bad debt (Art. 40(7)(d)); every outstanding figure subtracts it. 0 when none. */
  writtenOffAmount: number;
  /** 2026-09-22: the Art. 40(7) relief on this invoice as a STRUCTURED fact — null when none. source recorded = written off here (its own entry, in this platform's return, box 7); migrated = claimed in the previous system (Batch 1C), the item open at its outstanding amount here. */
  badDebtRelief: BadDebtRelief | null;
  /**
     * On a recovery_invoice: the receivable it recovers (Art. 40(9)); null otherwise.
     * @nullable
     */
  recoversInvoiceId: number | null;
  /**
     * On a recovery_invoice: the receipt whose money it declares; its date is the document's date (the tax point) and supply date.
     * @nullable
     */
  recoveryPaymentId: number | null;
  /** AP-2: the advance tax invoices this FINAL invoice adjusts (XML Standard ¶9.5 — one row per 386; allocationId set once issued). Empty on a note, an advance invoice, or an invoice adjusting nothing. */
  prepayments: InvoicePrepayment[];
  /** BT-113 — Σ prepayments.amount (VAT inclusive). Computed from adjusted advance tax invoices only, never from paidAmount. */
  prepaidAmount: number;
  /** total − prepaidAmount: what the customer still owes at issue (BT-115). The outstanding after cash is total − paidAmount − creditedAmount as before (the folded advance sits in paidAmount once issued). */
  amountDue: number;
  items?: InvoiceItem[];
}

